const envelope = $input || {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');
const envelopeKeys = new Set(['pluginId', 'widgetId', 'product', 'resource', 'submittedBy', 'submittedAt', 'action', 'fields']);
const unknownEnvelope = Object.keys(envelope).filter((key) => !envelopeKeys.has(key));
if (unknownEnvelope.length) throw new Error('unknown_envelope_fields:' + unknownEnvelope.join(','));
const product = text(envelope.product);
const resource = text(envelope.resource);
const submittedBy = text(envelope.submittedBy);
if (!submittedBy) throw new Error('submitted_by_required');
const fields = envelope.fields && typeof envelope.fields === 'object' && !Array.isArray(envelope.fields) ? envelope.fields : null;
if (!fields) throw new Error('fields_required');
if (product !== 'city') throw new Error('unsupported_product');
if (resource !== 'incidents') throw new Error('unsupported_resource');
const recordId = text(fields.incident_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(recordId)) throw new Error('record_id_invalid');
const encodedId = encodeURIComponent(recordId);
const allowed = new Set(["incident_id","notes"]);
const unknown = Object.keys(fields).filter((key) => !allowed.has(key));
if (unknown.length) throw new Error('unknown_fields:' + unknown.join(','));
const notes = text(fields.notes);
if (notes.length > 4000) throw new Error('notes_max_4000');
const patch = { status: 'closed', closed_at: $now, ...(notes ? { resolution_notes: notes } : {}) };
const audit = {
  product, resource, operation: 'incidents.close', recordId,
  pluginId: text(envelope.pluginId), widgetId: text(envelope.widgetId),
  submittedBy, submittedAt: text(envelope.submittedAt) || $now,
};

return { recordId, encodedId, patch, audit, operation: 'incidents.close' };

const response = $input || {};
const current = response.body;
const action = response.input;
if (response.statusCode !== 200 || !current || typeof current.data !== 'object' || !current.data) throw new Error('record_not_found');
const data = current.data;
if (!Number.isInteger(current.version)) throw new Error('record_version_unavailable');
if (!["reported","open","acknowledged","assigned","investigating","in_progress","waiting_approval","resolved"].includes(String(data.status))) throw new Error('record_status_invalid');



const INTERNAL_FIELDS = ["reported_by","contact_info","reporter_name","reporter_phone","reporter_email","reporter_id_card","internal_notes","internal_attachments","assigned_to","assigned_at","resolution_notes","merged_reporter_ids","maintenance_record_id","cost_status","cost_approved_at","cost_approval_id","cost_approved_by","cost_approval_roles","reporter_type","internal_comments","upvoters","merge_notes"];
const publicComment = (entry) => {
  if (!entry || typeof entry !== 'object' || entry.is_internal === true) return null;
  const clean = {};
  for (const key of ['id', 'comment', 'posted_at', 'created_at']) {
    if (entry[key] !== undefined) clean[key] = entry[key];
  }
  clean.is_internal = false;
  if (entry.public_author === true && entry.user_name) clean.user_name = entry.user_name;
  return clean;
};
const publicRecord = (data) => {
  const next = { ...data };
  for (const field of INTERNAL_FIELDS) delete next[field];
  next.comments = (Array.isArray(data.comments) ? data.comments : []).map(publicComment).filter(Boolean);
  return next;
};
const legacyInternal = (data) => {
  const internal = {};
  for (const field of INTERNAL_FIELDS) {
    if (field === 'internal_comments') continue;
    if (data[field] !== undefined) internal[field] = data[field];
  }
  const comments = (Array.isArray(data.comments) ? data.comments : []).filter((entry) => entry && entry.is_internal === true);
  if (comments.length) internal.internal_comments = comments;
  return internal;
};

const next = publicRecord(data);

const publicPatch = { status: 'closed', closed_at: action.patch.closed_at };
const sidecarPatch = legacyInternal(data);
if (action.patch.resolution_notes !== undefined) sidecarPatch.resolution_notes = action.patch.resolution_notes;

Object.assign(next, publicPatch);
const internalId = 'internal-' + action.recordId;
return {
  body: { data: next, ifVersion: current.version, publish: false },
  encodedId: action.encodedId,
  recordId: action.recordId,
  internalId,
  sidecarPatch,
  sidecarQuery: { where: { or: [{ id: internalId }, { id: action.recordId }] }, limit: 2 },
  audit: action.audit,
  operation: action.operation,


};

const response = $input || {};
const plan = response.input;
if (response.statusCode !== 200 || !response.body || !Array.isArray(response.body.items)) throw new Error('sidecar_query_failed');
const item = response.body.items.find((entry) => String(entry.id) === plan.internalId)
  || response.body.items.find((entry) => String(entry.id) === plan.recordId)
  || null;
const exists = Boolean(item && Number.isInteger(item.version));
const current = exists ? item.data : {};
const sidecarId = exists ? String(item.id) : plan.internalId;
const data = { ...current, ...plan.sidecarPatch };
if (Array.isArray(data.internal_comments)) {
  const seen = new Set();
  data.internal_comments = data.internal_comments.filter((entry) => {
    const key = entry && entry.id ? String(entry.id) : JSON.stringify(entry);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}
if (plan.operation === 'incidents.upvote') {
  const upvoters = (Array.isArray(data.upvoters) ? data.upvoters : []).map(String).filter(Boolean);
  const already = upvoters.includes(plan.submitter);
  if (!already) upvoters.push(plan.submitter);
  data.upvoters = upvoters;
  plan.body.data.upvotes = (Number.isInteger(plan.body.data.upvotes) ? plan.body.data.upvotes : 0) + (already ? 0 : 1);
  plan.upvotes = plan.body.data.upvotes;
  plan.upvoters = upvoters;
}
data.id = sidecarId;
data.incident_id = plan.recordId;
data.updated_at = $now;
const body = exists
  ? { data, ifVersion: item.version, publish: false }
  : { data, publish: false };
return {
  ...plan,
  sidecar: {
    exists,
    url: 'https://synapsedx.sbs/v1/capabilities/datasets/city-incident-internal/records/' + encodeURIComponent(sidecarId),
    body,
  },
};

const response = $input || {};
const state = response.input || {};
if (![200, 201].includes(response.statusCode)) throw new Error('incident_write_failed');
return {
  operation: state.operation,
  incident_id: state.recordId,
  audit: state.audit,


};
